description:
Implement a `createEventBus` factory that returns `{ useEmit, useOn }`. Components can publish typed events with `useEmit` and subscribe to them with `useOn`. Listeners must be cleaned up on unmount.

**Example:**
```tsx
const bus = createEventBus<{ greet: string; ping: void }>();

function Sender() {
  const emit = bus.useEmit();
  return <button onClick={() => emit('greet', 'hello')}>Send</button>;
}

function Receiver() {
  const [msg, setMsg] = useState('');
  bus.useOn('greet', (payload) => setMsg(payload));
  return <span>{msg}</span>;
}
```

