test_suite:
test('useOn receives event emitted by useEmit', () => {
  const bus = createEventBus<{ ping: string }>();
  const received: string[] = [];
  renderHook(() => bus.useOn('ping', (v) => received.push(v)));
  const { result } = renderHook(() => bus.useEmit());
  act(() => result.current('ping', 'hello'));
  expect(received).toEqual(['hello']);
});

test('useOn does not receive events for different channel', () => {
  const bus = createEventBus<{ a: string; b: string }>();
  const received: string[] = [];
  renderHook(() => bus.useOn('a', (v) => received.push(v)));
  const { result } = renderHook(() => bus.useEmit());
  act(() => result.current('b', 'ignored'));
  expect(received).toHaveLength(0);
});

test('multiple listeners on same event all fire', () => {
  const bus = createEventBus<{ tick: number }>();
  const log: number[] = [];
  renderHook(() => bus.useOn('tick', (v) => log.push(v)));
  renderHook(() => bus.useOn('tick', (v) => log.push(v * 2)));
  const { result } = renderHook(() => bus.useEmit());
  act(() => result.current('tick', 5));
  expect(log).toEqual([5, 10]);
});

// __hidden__
test('listener is removed after unmount', () => {
  const bus = createEventBus<{ msg: string }>();
  const received: string[] = [];
  const { unmount } = renderHook(() => bus.useOn('msg', (v) => received.push(v)));
  const { result } = renderHook(() => bus.useEmit());
  act(() => result.current('msg', 'before'));
  unmount();
  act(() => result.current('msg', 'after'));
  expect(received).toEqual(['before']);
});

solution:
import { useEffect, useCallback, useRef } from 'react';

export function createEventBus<Events extends Record<string, any>>() {
  const listeners = new Map<keyof Events, Set<(payload: any) => void>>();

  function useOn<K extends keyof Events>(event: K, handler: (payload: Events[K]) => void) {
    const handlerRef = useRef(handler);
    handlerRef.current = handler;
    useEffect(() => {
      const stable = (p: Events[K]) => handlerRef.current(p);
      if (!listeners.has(event)) listeners.set(event, new Set());
      listeners.get(event)!.add(stable);
      return () => { listeners.get(event)?.delete(stable); };
    }, [event]);
  }

  function useEmit() {
    return useCallback(<K extends keyof Events>(event: K, payload: Events[K]) => {
      listeners.get(event)?.forEach(fn => fn(payload));
    }, []);
  }

  return { useOn, useEmit };
}
